    async def set_custom_field(
        self,
        id: str,
        *,
        operation: CustomFieldOperation,
        name: str,
        owner_id: str | NotGiven = NOT_GIVEN,
        value: str | NotGiven = NOT_GIVEN,
        end_user_id: str | None = None,
        conductor_end_user_id: str | None = None,
        idempotency_key: str | None = None,
        timeout: float | None = None,
        total_timeout: float | None = None,
        max_retries: int | None = None,
        server_timeout: int | None = None,
    ) -> CustomFieldValue:
        """Set a custom field on an item group.

        Adds, changes or removes one custom field value on an existing item group, chosen by `operation`. The field must already be defined for this kind of record (see custom-field-definitions). The response is the stored value; after `delete`, `type` and `value` are null. Our own private company marker is never readable or writable here: its owner ID is refused with `400 INVALID_PARAMETER`. Send an `Idempotency-Key` header so a retry after a network error never writes the value twice (the SDKs do this for you). See [Idempotency and safe retries](https://www.desktopaccountingapi.com/docs/guides/idempotency/). See [Custom fields](https://www.desktopaccountingapi.com/docs/quickbooks/custom-fields/).

        Operation ``qbd.itemGroups.setCustomField``: ``POST /v1/quickbooks-desktop/item-groups/{id}/custom-fields``.

        Args:
            id: QuickBooks ID of the item group.
            operation: `update` (qbXML DataExtMod) writes the value; for public fields (`ownerId` "0") it works whether or not the record has a value yet. `add` (DataExtAdd) gives a record its first value of a private field, the way an application initializes its own data. `delete` (DataExtDel) clears the value on this record and keeps the field definition.
            name: Name of the custom field, as defined in the company file.
            owner_id: "0" (the default) for the public custom fields people see in QuickBooks, or the GUID of the application that owns a private field. Our own company-marker owner is refused.
            value: The value to store, as text (QuickBooks stores numbers, dates and amounts as text too). Required for `add` and `update`; leave it out for `delete`.
            end_user_id: End user (``eu_...``) whose QuickBooks company file to use. Defaults to the client's ``end_user_id``.
            conductor_end_user_id: Alias of ``end_user_id`` with Conductor's name, for code ported from ``conductor-py``. Passing both with different values raises ``DaapiError``.
            idempotency_key: Makes the write safe to retry (``Idempotency-Key``). Defaults to a new UUID that is reused on every retry of this call.
            timeout: Client-side timeout in seconds for each HTTP attempt; also the time budget for waiting on a request that is still running in QuickBooks. Defaults to the client's ``timeout``.
            total_timeout: Time budget in seconds for the whole call: every attempt, retry backoff and the wait for a pending request. Defaults to the client's ``total_timeout`` (none).
            max_retries: Retries for network errors, 429 and retryable 5xx responses. Defaults to the client's ``max_retries``.
            server_timeout: Seconds the API waits for QuickBooks before answering (``Daapi-Timeout-Seconds``, 1-300). Defaults to the client's ``server_timeout`` or the API default.

        Returns:
            The CustomFieldValue object.
        """
        return await self._client._request(
            _QBD_ITEM_GROUPS_SET_CUSTOM_FIELD,
            "POST",
            "/v1/quickbooks-desktop/item-groups/" + _pp("id", id) + "/custom-fields",
            cast_to=CustomFieldValue.from_wire,
            body={
                "operation": operation,
                "name": name,
                "ownerId": owner_id,
                "value": value,
            },
            end_user_id=end_user_id,
            conductor_end_user_id=conductor_end_user_id,
            idempotency_key=idempotency_key,
            timeout=timeout,
            total_timeout=total_timeout,
            max_retries=max_retries,
            server_timeout=server_timeout,
        )

    async def update(
        self,
        id: str,
        *,
        revision_number: str,
        name: str | NotGiven = NOT_GIVEN,
        barcode: BarcodeUpdateInput | NotGiven = NOT_GIVEN,
        is_active: bool | NotGiven = NOT_GIVEN,
        description: str | NotGiven | None = NOT_GIVEN,
        unit_of_measure_set_id: str | NotGiven = NOT_GIVEN,
        force_unit_of_measure_change: bool | NotGiven = NOT_GIVEN,
        should_print_items_in_group: bool | NotGiven = NOT_GIVEN,
        clear_item_lines: bool | NotGiven = NOT_GIVEN,
        lines: Sequence[ItemGroupMemberLineUpdateInput] | NotGiven = NOT_GIVEN,
        end_user_id: str | None = None,
        conductor_end_user_id: str | None = None,
        idempotency_key: str | None = None,
        timeout: float | None = None,
        total_timeout: float | None = None,
        max_retries: int | None = None,
        server_timeout: int | None = None,
    ) -> ItemGroup:
        """Update an item group.

        Changes the fields you send on an existing item group and leaves omitted fields unchanged. Requires the current `revisionNumber`. A stale `revisionNumber` returns `409 QBD_REVISION_NUMBER_STALE`: retrieve the item group, reapply your change and send the new revision. Sending a line array replaces all existing lines of that kind. See [Updates and line items](https://www.desktopaccountingapi.com/docs/quickbooks/updates-and-line-items/).

        Operation ``qbd.itemGroups.update``: ``POST /v1/quickbooks-desktop/item-groups/{id}``.

        Args:
            id: QuickBooks ID of the item group.
            revision_number: Current revision of this item group. Send it unchanged when updating; a stale value is rejected. QuickBooks changes it at most once per second, so a second edit within the same second keeps the same value. This API spaces its own consecutive writes to one object by over a second; edits made elsewhere in the same second are not detected.
            name: Name of this item group, unique within its parent level.
            barcode: Barcode details for this item group.
            is_active: Whether this item group is active. Inactive objects stay in QuickBooks but are hidden from most lists.
            description: Description of this item group. Pass ``None`` to clear it.
            unit_of_measure_set_id: ID of the unit of measure set for this item group.
            force_unit_of_measure_change: Force unit of measure change of this item group.
            should_print_items_in_group: Whether to print items in group.
            clear_item_lines: Clear item lines of this item group. Replaces every existing line when present: keep a line by sending its id, add one with id "-1", omit the array to leave lines unchanged. Cannot be combined with lines.
            lines: Line items of this item group. Replaces every existing line when present: keep a line by sending its id, add one with id "-1", omit the array to leave lines unchanged. Cannot be combined with clearItemLines.
            end_user_id: End user (``eu_...``) whose QuickBooks company file to use. Defaults to the client's ``end_user_id``.
            conductor_end_user_id: Alias of ``end_user_id`` with Conductor's name, for code ported from ``conductor-py``. Passing both with different values raises ``DaapiError``.
            idempotency_key: Makes the write safe to retry (``Idempotency-Key``). Defaults to a new UUID that is reused on every retry of this call.
            timeout: Client-side timeout in seconds for each HTTP attempt; also the time budget for waiting on a request that is still running in QuickBooks. Defaults to the client's ``timeout``.
            total_timeout: Time budget in seconds for the whole call: every attempt, retry backoff and the wait for a pending request. Defaults to the client's ``total_timeout`` (none).
            max_retries: Retries for network errors, 429 and retryable 5xx responses. Defaults to the client's ``max_retries``.
            server_timeout: Seconds the API waits for QuickBooks before answering (``Daapi-Timeout-Seconds``, 1-300). Defaults to the client's ``server_timeout`` or the API default.

        Returns:
            The ItemGroup object.
        """
        return await self._client._request(
            _QBD_ITEM_GROUPS_UPDATE,
            "POST",
            "/v1/quickbooks-desktop/item-groups/" + _pp("id", id),
            cast_to=ItemGroup.from_wire,
            body={
                "revisionNumber": revision_number,
                "name": name,
                "barcode": barcode,
                "isActive": is_active,
                "description": description,
                "unitOfMeasureSetId": unit_of_measure_set_id,
                "forceUnitOfMeasureChange": force_unit_of_measure_change,
                "shouldPrintItemsInGroup": should_print_items_in_group,
                "clearItemLines": clear_item_lines,
                "lines": lines,
            },
            end_user_id=end_user_id,
            conductor_end_user_id=conductor_end_user_id,
            idempotency_key=idempotency_key,
            timeout=timeout,
            total_timeout=total_timeout,
            max_retries=max_retries,
            server_timeout=server_timeout,
        )
